#include <stdio.h>
#include <math.h>
#define TOLERANCE 1.0e-6
int main(void) {
    double x, term = 1.0, sum = 0.0;
    int n = 0;
    printf("Enter x (-5 to 5): ");
    scanf("%lf", &x);
    while (fabs(term) >= TOLERANCE) {
        sum += term;
        n++;
        term = term * x / n;
    }
    printf("e^%.2lf is approximately %.6lf\n", x, sum);
    printf("Terms used: %d\n", n);
    return 0;
}

#include <stdio.h>
#define INPUTFILE "raw.dat"
#define OUTPUTFILE "clean.dat"
#define LOW 0.0
#define HIGH 100.0
int main(void) {
    FILE *inFile, *outFile;
    double value;
    int total = 0, clamped = 0;
    inFile = fopen(INPUTFILE, "r");
    if (inFile == NULL) {
        printf("Error: cannot open %s\n", INPUTFILE);
        return 1;
    }
    outFile = fopen(OUTPUTFILE, "w");
    if (outFile == NULL) {
        printf("Error: cannot open %s\n", OUTPUTFILE);
        fclose(inFile);
        return 1;
    }
    while (fscanf(inFile, "%lf", &value) == 1) {
        total++;
        if (value > HIGH) {
            value = HIGH;
            clamped++;
        } else if (value < LOW) {
            value = LOW;
            clamped++;
        }
        fprintf(outFile, "%.2lf\n", value);
    }
    fclose(inFile);
    fclose(outFile);
    printf("Clamped %d of %d values.\n", clamped, total);
    return 0;
}

#include <stdio.h>
#include <math.h>
#define PI acos(-1.0)
int main(void) {
    int nRows, nCols, row, c;
    double x, value, maxValue = 0.0, maxX = 0.0;
    printf("Enter number of rows: ");
    scanf("%d", &nRows);
    printf("Enter number of columns: ");
    scanf("%d", &nCols);
    for (row = 1; row <= nRows; row++) {
        x = row * PI / nRows;
        printf("%.3lf", x);
        for (c = 1; c <= nCols; c++) {
            value = sin(c * x) / (1 + x);
            printf(" %7.4lf", value);
            if ((row == 1 && c == 1) || value > maxValue) {
                maxValue = value;
                maxX = x;
            }
        }
        printf("\n");
    }
    printf("Maximum output value of %.4lf\n", maxValue);
    printf("occurs at x = %.3lf\n", maxX);
    return 0;
}

/* Returns the number of 1 digits in the binary representation of n (n >= 0). */
int binaryOnes(int n) {
    int count = 0;
    while (n > 0) {
        if (n % 2 == 1)
            count++;
        n = n / 2;
    }
    return count;
}
